"use client";

import React, { useState } from 'react';
import Navigation from '../../components/Navigation';
import { useStorage } from '../../hooks/useStorage';
import { MOCK_PROVIDERS } from '../../lib/providers/mocks';
import OTPModal from '../../components/OTPModal';

export default function ConnectedServicesPage() {
  const { isHydrated, connections, actions } = useStorage();
  const [modalOpen, setModalOpen] = useState(false);
  const [selectedProvider, setSelectedProvider] = useState<{id: string, name: string} | null>(null);

  if (!isHydrated) {
    return <div style={{padding: '2rem'}}>Loading...</div>;
  }

  const handleConnectClick = (providerId: string, providerName: string, isConnected: boolean) => {
    if (isConnected) {
      actions.disconnectProvider(providerId);
    } else {
      setSelectedProvider({ id: providerId, name: providerName });
      setModalOpen(true);
    }
  };

  const handleOtpSuccess = () => {
    if (selectedProvider) {
      actions.connectProvider(selectedProvider.id);
      setModalOpen(false);
    }
  };

  return (
    <div>
      <Navigation />
      <div style={{maxWidth: '800px', margin: '0 auto', padding: '1rem'}}>
        <main style={{marginTop: '2rem'}}>
          <h2>Connected Services</h2>
          <div style={{background: '#fef08a', color: '#854d0e', padding: '1rem', borderRadius: '4px', marginBottom: '2rem'}}>
            <strong>⚠️ DEVELOPMENT / DEMO MODE</strong>
            <p style={{margin: '0.5rem 0 0 0'}}>
              This feature is currently in mock/demo state for architectural testing. CompareAll does NOT have actual access to your external accounts. Future versions will use authorized official APIs/OAuth.
            </p>
          </div>

          <p style={{color: 'var(--muted)', marginBottom: '2rem'}}>
            (Future Flow) Connect your accounts to view personalized discounts, subscriptions, and better matches.<br/>
            <strong>Privacy Promise:</strong> We will only use official OAuth when available. Passwords will never be stored.
          </p>

          <div className="provider-list" style={{display: 'flex', flexDirection: 'column', gap: '1rem'}}>
            {MOCK_PROVIDERS.map(provider => {
              const isConnected = connections.some(c => c.providerId === provider.config.id && c.status === 'connected');
              
              return (
                <div key={provider.config.id} className="provider-card" style={{display: 'flex', justifyContent: 'space-between', alignItems: 'center'}}>
                  <div>
                    <h3 style={{margin: '0 0 0.5rem 0'}}>{provider.config.name}</h3>
                    <div style={{color: 'var(--muted)', fontSize: '0.875rem'}}>Category: {provider.config.supportedCategories.join(', ')}</div>
                    <span style={{
                      display: 'inline-block',
                      background: 'var(--background)',
                      padding: '0.2rem 0.5rem',
                      borderRadius: '4px',
                      fontSize: '0.75rem',
                      marginTop: '0.5rem',
                      fontWeight: 'bold',
                      color: 'var(--muted)'
                    }}>MOCK PROVIDER</span>
                  </div>

                  <button 
                    onClick={() => handleConnectClick(provider.config.id, provider.config.name, isConnected)}
                    style={{
                      background: isConnected ? 'var(--background)' : 'var(--primary)',
                      color: isConnected ? 'var(--foreground)' : 'white',
                      border: isConnected ? '1px solid var(--border)' : 'none',
                      padding: '0.75rem 1.5rem',
                      borderRadius: '4px',
                      fontWeight: 'bold',
                      cursor: 'pointer'
                    }}
                  >
                    {isConnected ? 'Disconnect' : 'Connect Demo Account'}
                  </button>
                </div>
              );
            })}
          </div>
        </main>

        {selectedProvider && (
          <OTPModal 
            providerName={selectedProvider.name.replace('[MOCK] ', '').replace(' Clone', '')}
            isOpen={modalOpen}
            onClose={() => setModalOpen(false)}
            onSuccess={handleOtpSuccess}
          />
        )}
      </div>
    </div>
  );
}
